import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"About & Updates","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/about.md","filePath":"user-guide/settings/about.md","lastUpdated":1787586465000}'),s={name:"user-guide/settings/about.md"};function n(i,e,c,d,l,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="about-updates" tabindex="-1">About &amp; Updates <a class="header-anchor" href="#about-updates" aria-label="Permalink to &quot;About &amp; Updates&quot;">​</a></h1><p>The About page displays component versions, provides one-click access to user and system storage directories, and supports manual update checks and seamless in-place upgrades. The page is located at <strong>Settings → About</strong>.</p><h2 id="_1-component-versions-project-info" tabindex="-1">1. Component Versions &amp; Project Info <a class="header-anchor" href="#_1-component-versions-project-info" aria-label="Permalink to &quot;1. Component Versions &amp; Project Info&quot;">​</a></h2><p>The top section displays independent version numbers across Lertaro&#39;s four architectural components:</p><ul><li><strong>App Version</strong>: Foreground WPF user interface version.</li><li><strong>Core Version</strong>: Core search and indexing logic library version.</li><li><strong>Service Version</strong>: Background Windows indexing service version (text color dynamically indicates service connectivity and health).</li><li><strong>CLI Version</strong>: Command-line interactive utility <code>lff</code> version.</li></ul><p>Direct links to the official website, GitHub repository, and documentation center are provided below.</p><h2 id="_2-data-directories-5-stage-backup-rotation" tabindex="-1">2. Data Directories &amp; 5-Stage Backup Rotation <a class="header-anchor" href="#_2-data-directories-5-stage-backup-rotation" aria-label="Permalink to &quot;2. Data Directories &amp; 5-Stage Backup Rotation&quot;">​</a></h2><p>Clickable links directly open storage directories in File Explorer (folders are created automatically if they do not yet exist):</p><h3 id="user-data-directory" tabindex="-1">User Data Directory <a class="header-anchor" href="#user-data-directory" aria-label="Permalink to &quot;User Data Directory&quot;">​</a></h3><ul><li><strong>Contents</strong>: Stores per-user settings (<code>user-settings.json</code>), search and keyword history, user caches, and security certificates.</li><li><strong>5-Stage Backup Rotation</strong>: Whenever settings are saved, Lertaro automatically rotates existing configuration files to <code>user-settings.json.bak.1</code>, cascading up to <code>.bak.5</code>. Even in unexpected power cuts or misconfigurations, you can restore from the latest 5 backups.</li></ul><h3 id="machine-data-directory" tabindex="-1">Machine Data Directory <a class="header-anchor" href="#machine-data-directory" aria-label="Permalink to &quot;Machine Data Directory&quot;">​</a></h3><ul><li><strong>Contents</strong>: Stores machine-level configuration (<code>machine-settings.json</code>), persistent physical index caches, and background service logs.</li></ul><h3 id="storage-path-architecture" tabindex="-1">Storage Path Architecture <a class="header-anchor" href="#storage-path-architecture" aria-label="Permalink to &quot;Storage Path Architecture&quot;">​</a></h3><ul><li><strong>Installer Version</strong>: User data is placed in <code>%LocalAppData%\\Lertaro</code>, and machine data in <code>%ProgramData%\\Lertaro</code>.</li><li><strong>Portable Version</strong>: User data is placed in <code>Data\\Users\\&lt;SID hash&gt;</code>, and machine data in <code>Data\\Machine</code> next to the executable (see <a href="./../getting-started.html#portable-data-isolation-architecture"><strong>Portable Data Isolation</strong></a>).</li></ul><h2 id="_3-update-checks-in-place-upgrades" tabindex="-1">3. Update Checks &amp; In-Place Upgrades <a class="header-anchor" href="#_3-update-checks-in-place-upgrades" aria-label="Permalink to &quot;3. Update Checks &amp; In-Place Upgrades&quot;">​</a></h2><ul><li><strong>Check for Updates</strong>: Manually queries online repositories for newer releases with dynamic button state feedback (&quot;Checking for updates...&quot; → &quot;Up to date&quot; or release version details).</li><li><strong>Upgrade Paths When Updates Are Found</strong>: <ul><li><strong>Silent In-Place Update</strong> — Downloads and installs updates in the background, restarting Lertaro seamlessly.</li><li><strong>Go to Download Page</strong> — Opens the GitHub Releases page in your default browser for manual package downloads.</li></ul></li><li><strong>Permission Safety Notices</strong>: If running under a non-administrator account unable to restart the background service for in-place updates, a clear guidance banner directs you to the manual download page.</li></ul>',16)])])}const h=a(s,[["render",n]]);export{g as __pageData,h as default};
